/* Spawns a spinning shard (type 0x70) at pos with velocity vel, tinted r/g/b, fading out over life. */
char *spawn_glow_particle(void *owner, void *pos, void *vel, float scale, int life,
                        unsigned char r, unsigned char g, unsigned char b, unsigned char a) {
    char *m = CreateMoby(0x70);
    if (m != 0) {
        struct GlowParticleVars *d = (struct GlowParticleVars *)((Moby *)m)->pvars;
        Vec4 tmp;
        Vec4 rot;
        int s;
        rot.q = 0;
        rot.f[0] = random_float_between(-3.1415927f, 3.1415927f);
        rot.f[1] = random_float_between(-3.1415927f, 3.1415927f);
        rot.f[2] = random_float_between(-3.1415927f, 3.1415927f);
        tmp = rot;
        m[0x20] = 0;
        m[0x23] = a;
        ((unsigned char *)m)[0x30] = 0xFF;
        ((Moby *)m)->draw_dist = 0xFF;
        m[0x31] = 1;
        set_moby_color(m, r, g, b);
        d->full_scale = ((Moby *)m)->scale * scale;
        *(int *)&((Moby *)m)->scale = 0;
        d->owner = owner;
        qcopy(m + 0x10, pos);
        qcopy(&d->velocity, vel);
        qcopy(m + 0x40, &tmp);
        d->life = life;
        s = *(unsigned short *)&d->life - scale_ticks(4);
        d->fade_start = s;
        ((Moby *)m)->scale = IntToFloat(d->life - (short)s) * d->full_scale / IntToFloat(d->life);
        d->alpha = a;
        moby_build_matrix(m);
    }
    return m;
}
