/* updates a decaying moby: spins down its position fields and fades it out. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/unclassified_002aa670.c, FUN_L00_002acad8. */
void update_glow_particle(M_d *m) {
    V_d *v = m->v;
    float a, b;
    int n;
    a = IntToFloat(v->n - v->h1c);
    b = IntToFloat(v->n);
    m->f2c = a * v->f18 / b;
    m->r[0] = FastAddRots(m->r[0], g_frame_time * 3.1415927f);
    m->r[1] = FastAddRots(m->r[1], g_frame_time * 3.1415927f);
    m->r[2] = FastAddRots(m->r[2], g_frame_time * 3.1415927f);
    if (FastDecTimer(&v->h1c)) {
        DeleteMoby(m);
        return;
    }
    n = v->n / 2;
    if (v->h1c < n) {
        m->b23 = v->h1c * v->h1e / n;
    }
}
