/* Draws two spinning textured quads around the moby, oriented by its velocity. */
void draw_bomb_landing_marker(char *moby) {
    QuadPkt q;
    float M[4][4];
    float E[4][4];
    float rot1[4];
    float rot2[4];
    PV_2acbf0_002acbf0 *pv = ((M_2acbf0_002acbf0 *)moby)->pv;
    s32 i;

    if (cinematic_mode == 2) return;
    for (i = 0; i < 2; i++) {
        s32 odd = i & 1;
        f32 ang;
        f32 den;
        f32 r;
        s32 kind;
        f32 x = pv->f20;
        f32 z = pv->f28;
        rot1[0] = FastAddRots(-fast_atan2(vec_length(x * x + z * z), pv->f24), 1.5707964f);
        rot1[1] = fast_atan2(pv->f28, pv->f20);
        rot1[2] = 0;
        rot1[3] = 0;
        rot2[0] = 0;
        ang = IntToFloat(level_frame_counter % scale_ticks(180));
        den = multiply_global_factor(180.0f);
        ang *= 6.2831855f;
        r = FastNormalizeAngle(ang / den);
        if (odd) r = -r;
        rot2[1] = r;
        rot2[2] = 0;
        rot2[3] = 0;
        euler_to_matrix(E, rot2);
        euler_to_matrix(M, rot1);
        sce_vu0_mul_matrix(M, M, E);
        qcopy(M[3], &pv->pos);
        kind = 0x11;
        if (odd) kind = 0x12;
        q.rgba[0] = 0x80808080;
        q.rgba[1] = 0x80808080;
        q.rgba[2] = 0x80808080;
        q.rgba[3] = 0x80808080;
        q.gs[1] = GetEffectTex(kind);
        q.gs[2] = 0xFF9000000260;
        q.gs[3] = 0x8000000048;
        q.gs[0] = 0;
        q.v[0][0] = -1.0f; q.v[0][1] = 0; q.v[0][2] = 1.0f; q.v[0][3] = 1.0f;
        q.v[1][0] = 1.0f; q.v[1][1] = 0; q.v[1][2] = 1.0f; q.v[1][3] = 1.0f;
        q.v[2][0] = -1.0f; q.v[2][1] = 0; q.v[2][2] = -1.0f; q.v[2][3] = 1.0f;
        q.v[3][0] = 1.0f; q.v[3][1] = 0; q.v[3][2] = -1.0f; q.v[3][3] = 1.0f;
        q.uv[0][0] = 0; q.uv[0][1] = 1.0f;
        q.uv[1][0] = 1.0f; q.uv[1][1] = 1.0f;
        q.uv[2][0] = 0; q.uv[2][1] = 0;
        q.uv[3][0] = 1.0f; q.uv[3][1] = 0;
        draw_world_quad(&q, M, 1);
    }
}
