/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/unclassified_002aa670.c, FUN_L00_002affa8. */
void select_gold_devastator_missile_target(char *self, O *out, char *skip) {
    Vec4 v;
    Vec4 lv;
    char *o;
    s32 p;
    s32 i;
    s32 flag;
    f32 best, yaw, pitch, dist, ang, z, angh, angv;
    char *spos;
    char *opos;
    P *g;

    i = 0;
    best = 10000.0f;
    yaw = *(f32 *)(self + 0x48);
    pitch = *(f32 *)(self + 0x44);
    o = active_mobies[i];
    if (o == 0) return;
    g = &g_hero;
    while (o != 0) {
        if (*(s8 *)(o + 0x20) < 0) goto next;
        if (o == skip) goto next;
        qcopy(&v, o + 0x10);
        spos = self + 0x10;
        opos = o + 0x10;
        if (40.0f < FastVecDist(&v, spos)) goto next;
        p = GetFlaggedPvarWord_r(o);
        if (p == 0) goto np;
        if (p <= 0x100000) goto np;
        if (0x3FFFFF < p) goto np;
        { f32 pf = *(f32 *)(p + 0x10); z = v.f[2] + pf; }
        goto zset;
    np:
        p = 0;
        z = v.f[2] + 0.5f;
    zset:
        v.f[2] = z;
        if (o == 0) goto next;
        if (*(char **)(o + 0x24) == 0) goto next;
        if (*(s16 *)(*(char **)(o + 0x24) + 0x46) != 5) goto next;
        angh = fast_atan2(v.f[0] - *(f32 *)(self + 0x10), v.f[1] - *(f32 *)(self + 0x14));
        angv = fast_atan2(vec_distance_xy(spos, &v), v.f[2] - *(f32 *)(self + 0x18));
        dist = FastVecDist(spos, &v);
        if (dist < 2.5f) {
            char *cam = g->cam;
            if (FastDiffRots(*(f32 *)(cam + 0x48),
                    fast_atan2(*(f32 *)(o + 0x10) - g->x80, *(f32 *)(o + 0x14) - g->x84)) < 1.0471976f) {
                if (FastAbsF(angv) < 0.7853982f) return;
            }
        }
        if (best < dist) goto next;
        ang = IntToFloat(gold_weapon_purchased.bB) * 0.6981317f;
        BuildSphericalOffset(&lv, dist, yaw, pitch + g->f2E4 * 0.5f);
        FastVecAdd(&lv, &lv, spos);
        z = FastArcSin(FastVecDist(&lv, &v) / (dist + dist));
        ang = ang + 1.5707964f;
        if (ang < z + z && p != 0) {
            ang = IntToFloat(*(u8 *)(p + 0xA) << 3) * 0.125f;
            FastArcSin(ang / dist);
        }
        flag = 1;
        if (coll_line_r(g_debug_camera, &v, 6, self, 0) != 0) {
            s32 hit = coll_hit_result[6];
            if (hit == 0 || hit != (s32)o) flag = 0;
        } else {
            best = dist;
            pitch = -angv;
            yaw = angh;
            if (find_listed_moby_by_data_id(o) != 0) goto next;
            z = 0.5f;
            out->owner = o;
            if (p != 0) z = *(f32 *)(p + 0x10);
            out->f2C = angh;
            out->w38 = flag;
            out->f30 = pitch;
            out->w24 = 0;
            out->w28 = 0;
            out->w20 = 0;
            qcopy(out, opos);
            out->f1C = z;
        }
    next:
        i++;
        o = active_mobies[i];
    }
}
