        if(p) { unsigned char texture=*part_type23_textures; p[3]=0x44; p[2]=texture; }
        smoke1688((&m->pos),phase.collision.dir,scale_ticks(7),127,0xB0B0B0,3,40000.0f,1000.0f,1.0f,-0.0004f,0.0f);
